def InvocationRequiresActiveFunction():
    for iid in inv_status:
        if inv_status[iid] == "IN_PROGRESS":
            fid = inv_func[iid]
            if fid in func_status:
                if func_status[fid] != "ACTIVE":
                    return False
    return True


# check: every existing item belongs to an ACTIVE table

def ItemRequiresActiveTable():
    for oid in item_status:
        if item_status[oid] == "EXISTS":
            tid = item_table[oid]
            if tid in table_status:
                if table_status[tid] != "ACTIVE":
                    return False
    return True
